  GameOver() {
    if (this.score > this.record) {
      this.record = this.score;
      PlayerPrefs.SetInt("record", this.record);
    }
    this.Afficher();
    this.finDePartie.SetActive(true);
    Audio.Play("lose");
  }

  Rejouer() {
    SceneManager.ReloadScene();
  }
